          return false;
      } 
      if (document.getElementById('SC_fast_search_' + pos).value == '__Clear_Fast__')
      { 
          document.getElementById('SC_fast_search_' + pos).value = '';
      } 
      out_qsearch = $('#fast_search_f0_' + pos).val();
